% denoise_ct.m
% Removes the cat scan noise from a speech recording.
%
% Idea
%   1. Take the STFT, a grid of cells; each cell has a magnitude and a phase.
%   2. Measure the noise level at each frequency from a noise-only stretch
%      (the first 0.2 s), using the median across that stretch's frames.
%   3. Subtract that noise level from every cell's magnitude (linear values, not dB).
%   4. Cells quieter than the noise level keep only a small fraction of their
%      original magnitude, so the background stays steady instead of switching on and off.
%   5. Keep every cell's original phase and convert back to audio with istft.
%

clear;


inFile    = 'catscan2.wav';
outFile   = 'catscan2_clean.wav';
gapStart  = 0;      
gapEnd    = 0.2;    
winLen    = 1024;   % samples
overlap   = 768;    % 75% of 1024
nfft      = 1024;
floorFrac = [];    


[x, fs] = audioread(inFile);
x = x(:, 1);
N = length(x);

% Padding with zeros, which we cut off again at the end:
%  (a) The window is almost zero at its edges, so the very first and last samples
%      are covered by only one frame, at its weakest point. After we change the
%      magnitudes, istft divides by that tiny weight there and the result blows
%      up. winLen zeros at each end move that problem into padding we throw away.
%  (b) istft rebuilds the full length only if (length - overlap)/(winLen - overlap)
%      is a whole number, so a few extra zeros go at the end as well.
hop      = winLen - overlap;
padStart = winLen;
padEnd   = winLen + mod(-(N + padStart + winLen - overlap), hop);
xPad     = [zeros(padStart, 1); x; zeros(padEnd, 1)];

%%\ 2. STFT: magnitude and phase of every cell
win = hann(winLen, 'periodic');
[S, ~, t] = stft(xPad, fs, 'Window', win, 'OverlapLength', overlap, 'FFTLength', nfft);

M  = abs(S);     % magnitude: how strong each cell is (linear, not dB)
Ph = angle(S);   % phase: kept exactly as it is in the recording

%%\ 3. Noise level n for each frequency, from the noise-only stretch
% Count only frames whose whole window lies inside the gap. These bounds are
% on the safe side whether t marks the start or the centre of each window.
winDur  = winLen / fs;
tReal   = t - padStart / fs;   % frame times measured on the real recording, padding removed
inGap   = (tReal >= gapStart + winDur/2) & (tReal <= gapEnd - winDur);
nFrames = nnz(inGap);
if nFrames < 5
    error('Only %d frames fall inside the gap. Widen the gap or shorten the window.', nFrames);
end

n = median(M(:, inGap), 2);   % one noise level per frequency row (median over the gap frames)

%%\ 4. First pass: subtract and set cells below the noise level to 0
Mzero = max(M - n, 0);

% What is left in the gap after that pass, compared with what was there originally
if isempty(floorFrac)
    leftover  = mean(Mzero(:, inGap), 'all');
    original  = mean(M(:, inGap), 'all');
    floorFrac = leftover / original;
end

%%\ 5. Final pass: subtract; cells below the noise level keep a fraction of their original magnitude
Mclean = M - n;
below  = M < n;
Mclean(below) = floorFrac * M(below);

%%\ 6. Back to audio: new magnitudes with the original phases, then inverse STFT
Sclean = Mclean .* exp(1j * Ph);
y = istft(Sclean, fs, 'Window', win, 'OverlapLength', overlap, 'FFTLength', nfft);
y = real(y(padStart + 1 : padStart + N));   % cut the padding off: same length as the original

% Peak before any scaling. A value far above the original's peak means a spike
% somewhere, and scaling it down would make the rest of the audio too quiet to hear.
peak = max(abs(y));
fprintf('Peak of the cleaned signal: %.3f (original: %.3f)\n', peak, max(abs(x))); %[output:42fc1c58]
if peak > 1
    warning('Cleaned signal peaks at %.2f, so it is being scaled down. If the result is quiet, look for a spike with plot(y).', peak);
    y = 0.99 * y / peak;
end

audiowrite(outFile, y, fs);

%%\ Report and compare before / after
fprintf('Sample rate: %d Hz, length: %.2f s\n', fs, N / fs); %[output:5109df73]
fprintf('Frames used for the noise level: %d\n', nFrames); %[output:2328e2e3]
fprintf('Fraction kept in cells below the noise level: %.3f\n', floorFrac); %[output:63cc5716]
fprintf('Saved: %s\n', outFile); %[output:004fe710]

figure; %[output:0548e65f]
subplot(2, 1, 1); %[output:0548e65f]
spectrogram(x, win, overlap, nfft, fs, 'yaxis'); %[output:0548e65f]
title('Original'); %[output:0548e65f]
c = caxis;
subplot(2, 1, 2); %[output:0548e65f]
spectrogram(y, win, overlap, nfft, fs, 'yaxis'); %[output:0548e65f]
title('Cleaned'); %[output:0548e65f]
caxis(c);   % same colour scale so the two plots can be compared %[output:0548e65f]

sound(x, fs); pause(length(x) / fs + 0.5); sound(y, fs);   % uncomment to listen
%%
 disp(any(isnan(y)))          % 1 means NaN values got in
 disp(max(abs(y)))            % 0 or tiny means the output really is silent
 disp([nFrames floorFrac])    % what the script used
 disp(max(abs(x)))            % peak of the original, for comparison
 disp([max(M(:)) max(n)])     % loudest cell vs loudest noise level
 disp(size(x)); disp(size(y)) % should match
%%
 yRaw = real(istft(Sclean, fs, 'Window', win, 'OverlapLength', overlap, 'FFTLength', nfft));
 y0   = real(istft(S,      fs, 'Window', win, 'OverlapLength', overlap, 'FFTLength', nfft));
 disp(max(abs(y0(1:N) - x)))                   % close to 0 means the round trip alone is fine
 [pk, i] = max(abs(yRaw));  disp([pk, i/fs])   % biggest raw value, and the time it happens
 figure; plot((1:numel(yRaw))/fs, yRaw)        % the cleaned signal before any scaling

